export interface RosterEntry {
  readonly id: string;
  readonly displayName: string;
}

export interface RosterPage {
  readonly page: number;
  readonly complete: boolean;
  readonly entries: readonly RosterEntry[];
}

export function mergeRosterPages(
  pages: readonly RosterPage[],
): { entries: RosterEntry[]; complete: boolean } {
  const pageNumbers = new Set<number>();
  for (const page of pages) {
    if (!Number.isInteger(page.page) || page.page < 0 || pageNumbers.has(page.page)) {
      throw new TypeError("Invalid or duplicate page number");
    }
    pageNumbers.add(page.page);
    for (const entry of page.entries) {
      if (entry.id.length === 0 || entry.displayName.length === 0) {
        throw new TypeError("Invalid roster entry");
      }
    }
  }

  const ordered = [...pages].sort((a, b) => a.page - b.page);
  const ids = new Set<string>();
  const entries: RosterEntry[] = [];
  for (const page of ordered) {
    for (const entry of page.entries) {
      if (!ids.has(entry.id)) {
        ids.add(entry.id);
        entries.push({ id: entry.id, displayName: entry.displayName });
      }
    }
  }
  return {
    entries,
    complete: pages.every((page) => page.complete),
  };
}

