import { mergeRosterPages } from './solution';
import type { RosterPage, RosterEntry } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsTypeError(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  if (!(error instanceof TypeError)) throw new Error(message);
}

const empty = mergeRosterPages([]);
equal(empty.entries.length, 0, 'empty input has no entries');
equal(empty.complete, false, 'empty input is not complete');

const earlyEntries: RosterEntry[] = [
  { id: 'b', displayName: 'Bee first' },
  { id: 'a', displayName: 'Ay' },
];
const lateEntries: RosterEntry[] = [
  { id: 'b', displayName: 'Bee later' },
  { id: 'c', displayName: 'See' },
];
const pages: RosterPage[] = [
  { page: 8, complete: true, entries: lateEntries },
  { page: 2, complete: true, entries: earlyEntries },
  { page: 5, complete: true, entries: [{ id: 'd', displayName: 'Dee' }] },
];
const merged = mergeRosterPages(pages);
equal(merged.complete, true, 'all supplied complete pages yield complete true');
equal(merged.entries.length, 4, 'duplicate ids are omitted');
equal(merged.entries[0].id, 'b', 'ascending page order determines first entry');
equal(merged.entries[0].displayName, 'Bee first', 'first display name wins');
equal(merged.entries[1].id, 'a', 'within-page order preserved');
equal(merged.entries[2].id, 'd', 'middle page processed next');
equal(merged.entries[3].id, 'c', 'new late-page entry retained');
assert(merged.entries[0] !== earlyEntries[0], 'returned entries must be fresh objects');
equal(pages[0].page, 8, 'input page array order not mutated');
equal(lateEntries[0].displayName, 'Bee later', 'input entries not mutated');

(merged.entries as RosterEntry[])[0] = { id: 'changed', displayName: 'Changed' };
equal(earlyEntries[0].id, 'b', 'mutating result does not alter input');

const incomplete = mergeRosterPages([
  { page: 1, complete: true, entries: [] },
  { page: 4, complete: false, entries: [] },
]);
equal(incomplete.complete, false, 'one incomplete page makes result incomplete');
const singleEmptyPage = mergeRosterPages([{ page: 0, complete: true, entries: [] }]);
equal(singleEmptyPage.complete, true, 'a supplied complete page is complete even without entries');

throwsTypeError(() => mergeRosterPages([{ page: -1, complete: true, entries: [] }]), 'negative page rejected');
throwsTypeError(() => mergeRosterPages([{ page: 1.5, complete: true, entries: [] }]), 'fractional page rejected');
throwsTypeError(
  () => mergeRosterPages([{ page: 1, complete: true, entries: [] }, { page: 1, complete: false, entries: [] }]),
  'duplicate page number rejected',
);
throwsTypeError(
  () => mergeRosterPages([{ page: 0, complete: true, entries: [{ id: '', displayName: 'Name' }] }]),
  'empty entry id rejected',
);
throwsTypeError(
  () => mergeRosterPages([{ page: 0, complete: true, entries: [{ id: 'id', displayName: '' }] }]),
  'empty display name rejected',
);

